def is_authorish_line(text: str) -> bool:
    if not text:
        return False
    caps = re.findall(r"\b[A-Z][a-z]{2,}\b", text)
    if len(caps) < 4:
        return False
    if "," in text:
        return True
    if any(ch in text for ch in ("*", "∗", "⋆")):
        return True
