        if i == 0:
            for bbox, txt in extract_lines(page):
                if not txt:
                    continue
                mark = False
                if EMAIL_RE.search(txt):
                    mark = True
                if AFFIL_HINT_RE.search(txt):
                    mark = True
                if ARXIV_ID_RE.search(txt) or ARXIV_CLASS_RE.search(txt):
                    mark = True
                if txt.strip().lower() == "preprint":
                    mark = True
                if is_authorish_line(txt):
                    mark = True
