                    mark = True
                if re.search(r"(?i)equal contribution", txt):
                    mark = True
                if re.search(r"(?i)\bsupported\b", txt) and re.search(r"(?i)\b(NSF|ARO|DARPA|NIH)\b", txt):
                    mark = True
                if VENUE_LINE_RE.search(txt) or DATE_LOC_RE.search(txt) or DOI_RE.search(txt):
                    mark = True
                # Avoid marking the title block: it typically sits above Abstract and has no author markers.
                if abstract_y0 is not None and bbox[1] < abstract_y0 and not mark:
                    continue
