                    for r in word_rects_in_bbox(page, bbox, pad=0.5):
                        page.add_redact_annot(r, fill=(0, 0, 0))
                        redactions += 1
        # Pattern-based redactions
        patterns = list(global_pats)
        if i < ref_start:
            t = page.get_text("text")
            patterns += sorted(set(EMAIL_RE.findall(t)))
            patterns += sorted(author_names)
            # targeted affiliations
            for ph in (
                "Duke University",
                "Adobe",
                "Carnegie Mellon University",
                "Duke Kunshan University",
                "Cornell University",
                "Renmin University of China",
                "Georgia Institute of Technology",
            ):
