import re
import fitz

pat=re.compile(r"arXiv\s*:?\s*\d{4}\.\d{4,5}(?:v\d+)?", re.I)

def ref_start(doc):
    hdr=re.compile(r"(?im)^\s*(?:\d+\.)?\s*references\b")
    for j in range(doc.page_count):
        if hdr.search(doc[j].get_text('text')):
            return j
    return doc.page_count

for path in ['/root/paper1.pdf','/root/paper2.pdf','/root/paper3.pdf']:
    doc=fitz.open(path)
    rs=ref_start(doc)
    hits=[]
    for j in range(rs):
        t=doc[j].get_text('text')
        for m in pat.finditer(t):
            hits.append((j,m.group(0)))
    print(path,'pre-ref arxiv hits:',hits[:20])
    doc.close()
