{"summary": "Regenerate redacted PDFs using coordinate-based author-band removal", "command": "python3 - <<'PY'
from __future__ import annotations

import re
from pathlib import Path
import fitz

INPUTS = [Path(f"/root/paper{i}.pdf") for i in (1, 2, 3)]
OUTPUTS = [Path(f"/root/redacted/paper{i}.pdf") for i in (1, 2, 3)]

EMAIL_RE = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}")
ARXIV_RE = re.compile(r"arXiv\s*:?\s*\d{4}\.\d{4,5}(?:v\d+)?", re.I)
DOI_RE = re.compile(r"10\.\d{4,9}/[^\s\)\]\}<>\"']+", re.I)
URL_RE = re.compile(r"https?://\S+")
GITHUB_RE = re.compile(r"\bgithub\.com/([A-Za-z0-9_.-]+)/[^\s\)\]]+", re.I)

REF_HDR_RE = re.compile(r"(?im)^\s*(?:\d+\.)?\s*references\b")

AFFIL_HINT_RE = re.compile(r"(?i)\b(University|Institute|Laboratory|College|School\b|Department\b|Centre|Center|Inc\.|LLC\b|Ltd\.|Corporation\b|Adobe\b)\b")
VENUE_LINE_RE = re.compile(
    r"(?i)(interspeech\s*20\d{2}|icml\s+workshop|proceedings\s+of\s+the\s+international\s+conference\s+on\s+machine\s+learning|copyright\s+20\d{2}|\bkos,\s+greece\b|vancouver,\s+canada\b)"
)

SAFE_GITHUB_OWNERS = {"espnet", "kan-bayashi"}


def find_references_start(doc: fitz.Document) -> int:
    for i in range(doc.page_count):
        if REF_HDR_RE.search(doc[i].get_text("text")):
            return i
    for i in range(doc.page_count):
        if "references" in doc[i].get_text("text").lower():
            return i
    return doc.page_count


def find_word_y0(page: fitz.Page, word: str) -> float | None:
    ys = [w[1] for w in page.get_text("words") if w[4].strip() == word]
    return min(ys) if ys else None


def normalize_name(name: str) -> str:
    return " ".join(name.strip().split())


def author_variants(name: str) -> set[str]:
    # from e.g. "Hai Helen Li" => {"Hai Helen Li", "Hai Li"}
    parts = [p for p in re.split(r"\s+", name.strip()) if p]
    out = {normalize_name(name)}
    if len(parts) >= 2:
        out.add(f"{parts[0]} {parts[-1]}")
    return {x for x in out if len(x.split()) >= 2}


def parse_meta_authors(doc: fitz.Document) -> set[str]:
    meta = doc.metadata or {}
    a = meta.get("author") or ""
    if not a.strip():
        return set()
    parts = re.split(r"[;,]|\band\b", a)
    names = set()
    for p in parts:
        p = normalize_name(p)
        if len(p.split()) >= 2:
            names |= author_variants(p)
    return names


def detect_author_band_on_first_page(doc: fitz.Document) -> tuple[float, float] | None:
    page = doc[0]
    words = page.get_text("words")

    # Find the y position of the Abstract header
    abstract_y0 = None
    for w in words:
        if w[4] in {"Abstract", "ABSTRACT"}:
            abstract_y0 = w[1]
            break
    if abstract_y0 is None:
        return None

    # Identify a likely author-line start: first line above Abstract
    # that contains commas / affiliation hints / emails.
    d = page.get_text("dict")
    candidates = []
    for b in d.get("blocks", []):
        if b.get("type") != 0:
            continue
        bx0, by0, bx1, by1 = b.get("bbox", (0, 0, 0, 0))
        if by0 >= abstract_y0:
            continue
        parts = []
        for ln in b.get("lines", []):
            for sp in ln.get("spans", []):
                parts.append(sp.get("text", ""))
        txt = " ".join(parts)
        txtn = " ".join(txt.split())
        if not txtn:
            continue
        caps = re.findall(r"\b[A-Z][a-z]{2,}\b", txtn)
        if EMAIL_RE.search(txtn) or AFFIL_HINT_RE.search(txtn) or ARXIV_RE.search(txtn):
            candidates.append(by0)
            continue
        if txtn.count(",") >= 2 and len(caps) >= 4:
            candidates.append(by0)
            continue
    if not candidates:
        return None

    y_start = min(candidates)
    return (y_start, abstract_y0)


def names_from_author_band(page: fitz.Page, y0: float, y1: float) -> set[str]:
    # Extract text from words in y range and parse First Last patterns.
    band_words = [w[4] for w in page.get_text("words") if w[1] >= y0 - 0.5 and w[3] <= y1 + 0.5]
    band_text = " ".join(band_words)

    # capture First Last where Last may have trailing digits/symbols
    raw = re.findall(r"\b([A-Z][a-zA-Z'\-]+)\s+([A-Z][a-zA-Z'\-]+[^\s]*)", band_text)
    names = set()
    for first, last in raw:
        last_clean = re.sub(r"[^A-Za-z\-']+", "", last)
        if last_clean and last_clean[0].isupper() and len(last_clean) >= 2:
            nm = f"{first} {last_clean}"
            if len(nm.split()) == 2:
                names.add(nm)
    return names


def global_patterns(doc: fitz.Document, ref_start: int) -> list[str]:
    # Gather patterns to remove on all pages.
    patterns: list[str] = []

    pre_text = "\n".join(doc[i].get_text("text") for i in range(min(ref_start, doc.page_count)))
    patterns += sorted(set(ARXIV_RE.findall(pre_text)))
    patterns += sorted(set(DOI_RE.findall(pre_text)))

    # Venue/copyright lines everywhere
    for i in range(doc.page_count):
        for ln in doc[i].get_text("text").splitlines():
            s = " ".join(ln.strip().split())
            if not s:
                continue
            if VENUE_LINE_RE.search(s):
                patterns.append(s)
            if re.search(r"(?i)\bcorrespondence\b", s):
                patterns.append(s)

    # Specific status labels
    for leak in ("Preprint",):
        if leak in pre_text:
            patterns.append(leak)

    # Potentially identifying GitHub URLs before references
    for u in sorted(set(URL_RE.findall(pre_text))):
        m = GITHUB_RE.search(u)
        if not m:
            continue
        owner = m.group(1)
        if owner.lower() in SAFE_GITHUB_OWNERS:
            continue
        patterns.append(u.rstrip(").,"))
        patterns.append(re.sub(r"^https?://", "", u).rstrip(").,"))

    # Remove duplicates preserve order
    seen = set()
    out = []
    for p in patterns:
        p = " ".join(p.split())
        if p and p not in seen:
            seen.add(p)
            out.append(p)
    return out


def redact(inp: Path, out: Path) -> None:
    doc = fitz.open(inp)
    ref_start = find_references_start(doc)

    # clear identifying metadata
    doc.set_metadata({
        "title": doc.metadata.get("title", ""),
        "author": "",
        "subject": "",
        "keywords": "",
        "creator": "",
        "producer": "",
    })

    gpat = global_patterns(doc, ref_start)

    meta_names = parse_meta_authors(doc)

    # Determine author band on page 0 and extract additional names
    band = detect_author_band_on_first_page(doc)
    band_names = set()
    if band is not None:
        y0, y1 = band
        band_names = names_from_author_band(doc[0], y0, y1)

    author_names = set(meta_names)
    for n in band_names:
        author_names |= author_variants(n)

    # extra institutional phrases for paper3-like templates
    affiliation_phrases = {
        "Duke University",
        "Adobe",
        "Carnegie Mellon University",
        "Duke Kunshan University",
        "Cornell University",
        "Renmin University of China",
        "Georgia Institute of Technology",
        "San Jose, CA, USA",
        "Durham, NC, USA",
        "Durham, USA",
        "Kos, Greece",
        "Vancouver, Canada",
    }

    for i in range(doc.page_count):
        page = doc[i]
        tp = page.get_textpage()
        redactions = 0

        # Remove author+affiliation band on first page by coordinates
        if i == 0 and band is not None:
            y0, y1 = band
            for x0, wy0, x1, wy1, w, b, l, n in page.get_text("words"):
                if wy0 >= y0 - 0.5 and wy1 <= y1 + 0.5 and w not in {"Abstract", "ABSTRACT"}:
                    page.add_redact_annot(fitz.Rect(x0, wy0, x1, wy1), fill=(0, 0, 0))
                    redactions += 1

        # Redact patterns everywhere
        patterns = list(gpat)

        # Redact obvious affiliation phrases before references
        if i < ref_start:
            t = page.get_text("text")
            patterns += sorted(set(EMAIL_RE.findall(t)))
            for ph in affiliation_phrases:
                if ph in t:
                    patterns.append(ph)

            # Redact author names before references
            patterns += sorted(author_names)

        # Also remove equal contribution lines globally
        for ln in page.get_text("text").splitlines():
            s = " ".join(ln.strip().split())
            if re.search(r"(?i)equal contribution", s):
                patterns.append(s)

        # Grant tokens: remove unique-looking IDs (common in footnotes)
        for x0, y0w, x1, y1w, word, *_ in page.get_text("words"):
            if re.fullmatch(r"\d{6,}[A-Za-z0-9-]*\.?", word) or (re.fullmatch(r"[A-Z]{2,}\d[A-Z0-9-]*\.?", word) and any(c.isdigit() for c in word)):
                # avoid deleting normal page numbers: require it's near 'NSF'/'ARO'/'supported' on that line
                pass

        # Dedup patterns
        seen=set(); pats=[]
        for p in patterns:
            p = " ".join(str(p).split())
            if p and p not in seen:
                seen.add(p)
                pats.append(p)

        for pat in pats:
            for r in page.search_for(pat, textpage=tp):
                page.add_redact_annot(r, fill=(0, 0, 0))
                redactions += 1

        if redactions:
            page.apply_redactions()

    out.parent.mkdir(parents=True, exist_ok=True)
    doc.save(out)
    doc.close()


def verify() -> None:
    for inp, out in zip(INPUTS, OUTPUTS):
        if not out.exists() or out.stat().st_size == 0:
            raise SystemExit(f"Missing output: {out}")
        o = fitz.open(inp)
        r = fitz.open(out)
        if o.page_count != r.page_count:
            raise SystemExit(f"Page count changed: {out}")

        orig_len = sum(len(p.get_text()) for p in o)
        red_len = sum(len(p.get_text()) for p in r)
        if orig_len and red_len < orig_len * 0.80:
            raise SystemExit(f"Too much removed for {out}: kept {red_len/orig_len:.1%}")

        # Email leakage
        ref_start = find_references_start(o)
        before = "\n".join(r[i].get_text("text") for i in range(min(ref_start, r.page_count)))
        if EMAIL_RE.search(before):
            raise SystemExit(f"Email leakage remains in {out}")

        # arXiv leakage: only those appearing pre-ref in original must be removed globally
        pre = "\n".join(o[i].get_text("text") for i in range(min(ref_start, o.page_count)))
        for ax in set(ARXIV_RE.findall(pre)):
            if ax in "\n".join(r[i].get_text("text") for i in range(r.page_count)):
                raise SystemExit(f"arXiv leakage remains in {out}: {ax}")

        # metadata author cleared
        if (r.metadata.get("author") or "").strip():
            raise SystemExit(f"Metadata author not cleared: {out}")

        o.close(); r.close()


for inp, out in zip(INPUTS, OUTPUTS):
    redact(inp, out)

verify()
print('Regenerated /root/redacted/paper{1-3}.pdf and verified.')
PY", "security_risk": "MEDIUM"}

