        if "references" in doc[i].get_text("text").lower():
            return i
    return doc.page_count


def find_word_y0(page: fitz.Page, word: str) -> float | None:
    ys = [w[1] for w in page.get_text("words") if w[4].strip() == word]
    return min(ys) if ys else None


def normalize_name(name: str) -> str:
    return " ".join(name.strip().split())


def author_variants(name: str) -> set[str]:
    # from e.g. "Hai Helen Li" => {"Hai Helen Li", "Hai Li"}
    parts = [p for p in re.split(r"\s+", name.strip()) if p]
