    seen = set()
    out = []
    for p in patterns:
        p = " ".join(p.split())
        if p and p not in seen:
            seen.add(p)
            out.append(p)
    return out


def redact(inp: Path, out: Path) -> None:
    doc = fitz.open(inp)
    ref_start = find_references_start(doc)

    # clear identifying metadata
    doc.set_metadata({
        "title": doc.metadata.get("title", ""),
        "author": "",
        "subject": "",
        "keywords": "",
        "creator": "",
        "producer": "",
    })

    gpat = global_patterns(doc, ref_start)

    meta_names = parse_meta_authors(doc)

    # Determine author band on page 0 and extract additional names
    band = detect_author_band_on_first_page(doc)
    band_names = set()
    if band is not None:
        y0, y1 = band
        band_names = names_from_author_band(doc[0], y0, y1)

    author_names = set(meta_names)
    for n in band_names:
        author_names |= author_variants(n)

    # extra institutional phrases for paper3-like templates
    affiliation_phrases = {
        "Duke University",
        "Adobe",
        "Carnegie Mellon University",
        "Duke Kunshan University",
        "Cornell University",
        "Renmin University of China",
        "Georgia Institute of Technology",
        "San Jose, CA, USA",
        "Durham, NC, USA",
        "Durham, USA",
        "Kos, Greece",
        "Vancouver, Canada",
    }

    for i in range(doc.page_count):
        page = doc[i]
        tp = page.get_textpage()
        redactions = 0

        # Remove author+affiliation band on first page by coordinates
        if i == 0 and band is not None:
            y0, y1 = band
            for x0, wy0, x1, wy1, w, b, l, n in page.get_text("words"):
                if wy0 >= y0 - 0.5 and wy1 <= y1 + 0.5 and w not in {"Abstract", "ABSTRACT"}:
                    page.add_redact_annot(fitz.Rect(x0, wy0, x1, wy1), fill=(0, 0, 0))
                    redactions += 1

        # Redact patterns everywhere
        patterns = list(gpat)

        # Redact obvious affiliation phrases before references
        if i < ref_start:
            t = page.get_text("text")
            patterns += sorted(set(EMAIL_RE.findall(t)))
            for ph in affiliation_phrases:
                if ph in t:
                    patterns.append(ph)

            # Redact author names before references
            patterns += sorted(author_names)

