for w in page.get_text('words'):
    if w[4] in {'Abstract','ABSTRACT'}:
        abstract_y0=w[1];break
print('abstract_y0',abstract_y0)

# dump lines
for b in page.get_text('dict')['blocks']:
    if b.get('type')!=0: continue
    for ln in b.get('lines',[]):
        bbox=ln['bbox']
        txt=normalize_ws(' '.join(sp.get('text','') for sp in ln.get('spans',[])))
        if not txt: continue
        mark=False
        reasons=[]
        if EMAIL_RE.search(txt): mark=True; reasons.append('email')
        if AFFIL_HINT_RE.search(txt): mark=True; reasons.append('affil')
        if ARXIV_ID_RE.search(txt): mark=True; reasons.append('arxiv_id')
        if ARXIV_CLASS_RE.search(txt): mark=True; reasons.append('arxiv_class')
        if txt.strip().lower()=='preprint': mark=True; reasons.append('preprint')
        if is_authorish_line(txt): mark=True; reasons.append('authorish')
        if re.search(r"(?i)\bcorrespondence\b", txt): mark=True; reasons.append('corr')
        if re.search(r"(?i)equal contribution", txt): mark=True; reasons.append('eq')
        if re.search(r"(?i)\bsupported\b", txt) and re.search(r"(?i)\b(NSF|ARO|DARPA|NIH)\b", txt): mark=True; reasons.append('fund')
        if VENUE_LINE_RE.search(txt) or DATE_LOC_RE.search(txt) or DOI_RE.search(txt): mark=True; reasons.append('venue/doi/date')
        # show top lines too
        flag = 'MARK' if mark else '    '
        print(f"{flag} y0={bbox[1]:.1f} y1={bbox[3]:.1f} :: {txt} :: {','.join(reasons)}")

doc.close()
