{"summary": "Fix over-redaction: refine author-line detection and avoid huge-bbox stamps", "command": "python3 - <<'PY'
from __future__ import annotations

import re
from pathlib import Path
import fitz

INPUTS = [Path(f"/root/paper{i}.pdf") for i in (1, 2, 3)]
OUTPUTS = [Path(f"/root/redacted/paper{i}.pdf") for i in (1, 2, 3)]

EMAIL_RE = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}")
ARXIV_ID_RE = re.compile(r"arXiv\s*:?\s*\d{4}\.\d{4,5}(?:v\d+)?", re.I)
ARXIV_CLASS_RE = re.compile(r"\[[a-z\-]+\.[A-Z]{2}\]", re.I)
ARXIV_DATE_RE = re.compile(r"\b\d{1,2}\s+[A-Za-z]{3}\s+20\d{2}\b")
DOI_RE = re.compile(r"10\.\d{4,9}/[^\s\)\]\}<>\"']+", re.I)
URL_RE = re.compile(r"https?://\S+")
GITHUB_RE = re.compile(r"\bgithub\.com/([A-Za-z0-9_.-]+)/[^\s\)\]]+", re.I)

REF_HDR_RE = re.compile(r"(?im)^\s*(?:\d+\.)?\s*references\b")

AFFIL_HINT_RE = re.compile(r"(?i)\b(University|Institute|Laboratory|College|School\b|Department\b|Centre|Center|Inc\.|LLC\b|Ltd\.|Corporation\b|Adobe\b)\b")
VENUE_LINE_RE = re.compile(
    r"(?i)(interspeech\s*20\d{2}|icml\s+workshop|proceedings\s+of\s+the\s+international\s+conference\s+on\s+machine\s+learning|copyright\s+20\d{2}|\bkos,\s+greece\b|vancouver,\s+canada\b)"
)
DATE_LOC_RE = re.compile(r"(?i)\b\d{1,2}\s*[-–]\s*\d{1,2}\s+\w+\s+20\d{2}\b|\b20\d{2}\b.*\b(greece|canada)\b")

SAFE_GITHUB_OWNERS = {"espnet", "kan-bayashi"}


def find_references_start(doc: fitz.Document) -> int:
    for i in range(doc.page_count):
        if REF_HDR_RE.search(doc[i].get_text("text")):
            return i
    for i in range(doc.page_count):
        if "references" in doc[i].get_text("text").lower():
            return i
    return doc.page_count


def normalize_ws(s: str) -> str:
    return " ".join(s.split())


def author_variants(name: str) -> set[str]:
    parts = [p for p in name.strip().split() if p]
    out = {normalize_ws(name)}
    if len(parts) >= 2:
        out.add(f"{parts[0]} {parts[-1]}")
    return {x for x in out if len(x.split()) >= 2}


def parse_meta_authors(doc: fitz.Document) -> set[str]:
    meta = doc.metadata or {}
    a = meta.get("author") or ""
    if not a.strip():
        return set()
    parts = re.split(r"[;,]|\band\b", a)
    names = set()
    for p in parts:
        p = normalize_ws(p)
        if len(p.split()) >= 2:
            names |= author_variants(p)
    return names


def extract_lines(page: fitz.Page):
    d = page.get_text("dict")
    for b in d.get("blocks", []):
        if b.get("type") != 0:
            continue
        for ln in b.get("lines", []):
            bbox = ln.get("bbox")
            text = " ".join(sp.get("text", "") for sp in ln.get("spans", []))
            yield bbox, normalize_ws(text)


def word_rects_in_bbox(page: fitz.Page, bbox, pad: float = 0.5):
    x0, y0, x1, y1 = bbox
    rect = fitz.Rect(x0 - pad, y0 - pad, x1 + pad, y1 + pad)
    for wx0, wy0, wx1, wy1, word, *_ in page.get_text("words"):
        wrect = fitz.Rect(wx0, wy0, wx1, wy1)
        if rect.intersects(wrect):
            yield wrect


def full_name_count(text: str) -> int:
    return len(re.findall(r"\b[A-Z][a-zA-Z'\-]{1,}\s+[A-Z][a-zA-Z'\-]{1,}\b", text))


def is_author_line(text: str) -> bool:
    if not text:
        return False
    fnc = full_name_count(text)
    if fnc < 4:
        return False
    comma_count = text.count(",")
    if comma_count >= 2:
        return True
    if any(ch in text for ch in ("*", "∗", "⋆", "♠", "♣", "†")):
        return True
    if len(re.findall(r"\b\d\b", text)) >= 2:
        return True
    return False


def gather_global_patterns(doc: fitz.Document, ref_start: int) -> list[str]:
    pre_text = "\n".join(doc[i].get_text("text") for i in range(min(ref_start, doc.page_count)))
    pats: list[str] = []

    pats += sorted(set(ARXIV_ID_RE.findall(pre_text)))
    pats += sorted(set(DOI_RE.findall(pre_text)))

    # arXiv class/date stamps on first page
    p0 = doc[0].get_text("text")
    pats += sorted(set(ARXIV_CLASS_RE.findall(p0)))
    # add date only if also arxiv class present
    if ARXIV_CLASS_RE.search(p0):
        pats += sorted(set(ARXIV_DATE_RE.findall(p0)))

    # venue/copyright lines everywhere
    for i in range(doc.page_count):
        t = doc[i].get_text("text")
        if "Preprint" in t:
            pats.append("Preprint")
        for ln in t.splitlines():
            s = normalize_ws(ln)
            if not s:
                continue
            if VENUE_LINE_RE.search(s) or DATE_LOC_RE.search(s):
                pats.append(s)
            if re.search(r"(?i)\bcorrespondence\b", s):
                pats.append(s)
            if re.search(r"(?i)equal contribution", s):
                pats.append(s)

    # identifying GitHub URLs pre-ref
    for u in sorted(set(URL_RE.findall(pre_text))):
        m = GITHUB_RE.search(u)
        if not m:
            continue
        owner = m.group(1)
        if owner.lower() in SAFE_GITHUB_OWNERS:
            continue
        pats.append(u.rstrip(").,"))
        pats.append(re.sub(r"^https?://", "", u).rstrip(").,"))

    # Dedup preserve order
    seen=set(); out=[]
    for p in pats:
        p = normalize_ws(str(p))
        if p and p not in seen:
            seen.add(p)
            out.append(p)
    return out


def redact(inp: Path, out: Path) -> None:
    doc = fitz.open(inp)
    ref_start = find_references_start(doc)

    doc.set_metadata({
        "title": doc.metadata.get("title", ""),
        "author": "",
        "subject": "",
        "keywords": "",
        "creator": "",
        "producer": "",
    })

    global_pats = gather_global_patterns(doc, ref_start)
    meta_names = parse_meta_authors(doc)

    # also extract names from first-page author lines
    band_names = set()
    for _, txt in extract_lines(doc[0]):
        if is_author_line(txt):
            raw = re.findall(r"\b([A-Z][a-zA-Z'\-]+)\s+([A-Z][a-zA-Z'\-]+[^\s]*)", txt)
            for first, last in raw:
                last_clean = re.sub(r"[^A-Za-z\-']+", "", last)
                if len(last_clean) >= 2:
                    band_names |= author_variants(f"{first} {last_clean}")

    author_names = set(meta_names)
    for n in band_names:
        author_names |= author_variants(n)

    # Abstract y0 on first page (to avoid touching content below)
    abstract_y0 = None
    for w in doc[0].get_text("words"):
        if w[4] in {"Abstract", "ABSTRACT"}:
            abstract_y0 = w[1]
            break

    for i in range(doc.page_count):
        page = doc[i]
        tp = page.get_textpage()
        redactions = 0

        # First page: redact author/affiliation/correspondence lines ABOVE abstract,
        # and venue/correspondence/funding lines ANYWHERE.
        if i == 0:
            for bbox, txt in extract_lines(page):
                if not txt:
                    continue
                h = bbox[3] - bbox[1]
                if h > 60:  # defensive: skip pathological bboxes
                    continue

                mark = False

                if abstract_y0 is not None and bbox[1] < abstract_y0:
                    if is_author_line(txt) or EMAIL_RE.search(txt) or AFFIL_HINT_RE.search(txt) or txt.strip().lower() == "preprint":
                        mark = True
                    if re.search(r"(?i)\bcorrespondence\b", txt):
                        mark = True

                # below abstract: still remove correspondence/funding/venue lines
                if re.search(r"(?i)\bcorrespondence\b", txt):
                    mark = True
                if re.search(r"(?i)equal contribution", txt):
                    mark = True
                if re.search(r"(?i)\bsupported\b", txt) and re.search(r"(?i)\b(NSF|ARO|DARPA|NIH)\b", txt):
                    mark = True
                if VENUE_LINE_RE.search(txt) or DATE_LOC_RE.search(txt) or DOI_RE.search(txt):
                    mark = True

                # DO NOT bbox-redact arXiv stamp: handled by search patterns
                if ARXIV_ID_RE.search(txt) or ARXIV_CLASS_RE.search(txt):
                    mark = False

                if mark:
                    for r in word_rects_in_bbox(page, bbox, pad=0.5):
                        page.add_redact_annot(r, fill=(0, 0, 0))
                        redactions += 1

        # Pattern-based: everywhere
        patterns = list(global_pats)

        if i < ref_start:
            t = page.get_text("text")
            patterns += sorted(set(EMAIL_RE.findall(t)))
            patterns += sorted(author_names)
            for ph in (
                "Duke University",
                "Adobe",
                "Carnegie Mellon University",
                "Duke Kunshan University",
                "Cornell University",
                "Renmin University of China",
                "Georgia Institute of Technology",
            ):
                if ph in t:
                    patterns.append(ph)

        seen=set(); pats=[]
        for p in patterns:
            p = normalize_ws(str(p))
            if p and p not in seen:
                seen.add(p)
                pats.append(p)

        for pat in pats:
            for r in page.search_for(pat, textpage=tp):
                page.add_redact_annot(r, fill=(0, 0, 0))
                redactions += 1

        if redactions:
            page.apply_redactions()

    out.parent.mkdir(parents=True, exist_ok=True)
    doc.save(out)
    doc.close()


def verify() -> None:
    for inp, out in zip(INPUTS, OUTPUTS):
        o = fitz.open(inp)
        r = fitz.open(out)

        if o.page_count != r.page_count:
            raise SystemExit(f"Page count changed: {out}")

        orig_len = sum(len(p.get_text()) for p in o)
        red_len = sum(len(p.get_text()) for p in r)
        if orig_len and red_len < orig_len * 0.80:
            raise SystemExit(f"Too much removed for {out}: kept {red_len/orig_len:.1%}")

        # check page 1 still has title-ish content (avoid wiping)
        head = r[0].get_text("text")
        if out.name == 'paper1.pdf' and 'VOICE' not in head.upper():
            raise SystemExit(f"paper1 title appears damaged in {out}")

        # email leakage before references
        ref_start = find_references_start(o)
        before = "\n".join(r[i].get_text("text") for i in range(min(ref_start, r.page_count)))
        if EMAIL_RE.search(before):
            raise SystemExit(f"Email leakage remains: {out}")

        # metadata author cleared
        if (r.metadata.get("author") or "").strip():
            raise SystemExit(f"Metadata author not cleared: {out}")

        o.close(); r.close()


for inp, out in zip(INPUTS, OUTPUTS):
    redact(inp, out)

verify()
print('Final redacted PDFs updated successfully.')
